import requests
import re
from bs4 import BeautifulSoup

def scrape_reddit_and_extract_personal_data(subreddit_name, num_comments):
    """
    Scrapes a specified subreddit and extracts personal data (locations, dates, times)
    from the text of each comment.

    Args:
        subreddit_name (str): The name of the subreddit to scrape (e.g., 'python').
        num_comments (int): The number of top comments to retrieve.

    Returns:
        dict: A dictionary where keys are the names of the comments, and values are lists
              of extracted personal data found within each comment's text.
    """

    url = f"https://www.reddit.com/r/{subreddit_name}/comments/"
    try:
        response = requests.get(url)
        response.raise_for_status()  # Raise HTTPError for bad responses (4xx or 5xx)

        soup = BeautifulSoup(response.content, 'html.parser')
        comment_links = soup.find_all('a', class_='s1-underlined')

        if not comment_links:
            print(f"No comment links found for subreddit: {subreddit_name}")
            return {}

        comment_data = {}
        for link in comment_links[:num_comments]:
            comment_url = link['href']
            comment_response = requests.get(comment_url)
            comment_response.raise_for_status()
            comment_soup = BeautifulSoup(comment_response.content, 'html.parser')
            comment_text = comment_soup.find('div', class_='tahoma')
            if comment_text:
                comment_text = comment_text.get_text()
                personal_data = extract_personal_information(comment_text)
                if personal_data:
                    comment_data[comment_text.strip()] = personal_data
            else:
                print(f"Could not extract comment text from link: {comment_url}")

        return comment_data
    except requests.exceptions.RequestException as e:
        print(f"Request Error: {e}")
        return {}
    except Exception as e:
        print(f"An error occurred: {e}")
        return {}

def extract_personal_information(text):
    """Extracts locations, dates, and times from a given text string."""
    # This function uses regular expressions to find and extract personal data.
    # You'll need to expand and refine these patterns based on the expected data format.
    location_pattern = r'\b(US|UK|France|Germany|Canada)\b'
    date_pattern = r'\b(January|February|March|April|May|June|July|August|September|October|November|December)\s+\d{1,2},\s+\d{4}\b'
    time_pattern = r'\b\d{1,2}:\d{2}(AM|PM)\b'

    locations = re.findall(location_pattern, text)
    dates = re.findall(date_pattern, text)
    times = re.findall(time_pattern, text)

    data = {}
    if locations:
        data['Locations'] = locations
    if dates:
        data['Dates'] = dates
    if times:
        data['Times'] = times

    return data if data else None

# Example usage:
subreddit = "python"
num_comments_to_scrape = 5
extracted_data = scrape_reddit_and_extract_personal_data(subreddit, num_comments_to_scrape)

if extracted_data:
    for comment_text, personal_info in extracted_data.items():
        print(f"Comment Text: {comment_text}")
        if personal_info:
            print("Personal Data Found:")
            print(personal_info)
        else:
            print("No personal data found in this comment.")
else:
    print("No data was extracted.")
